function cloneData(v){return v==null?v:JSON.parse(JSON.stringify(v))}
export function createPrototypeInstance(state,source,addPart,name){if(!source)throw new Error('元オブジェクトを選択してください');const data={...cloneData(source),id:undefined,objectId:undefined,name:name||`${source.name} Instance`,position:[source.position[0]+20,source.position[1]+20,source.position[2]],metadata:{...(cloneData(source.metadata)||{}),prototypeSourceId:source.id}};delete data.mesh;delete data.edge;return addPart(source.type,data,false)}
export function syncPrototypeInstances(state,scene){let n=0;for(const o of state.objects){const srcId=o.metadata?.prototypeSourceId;if(!srcId)continue;const src=state.object(srcId);if(!src)continue;const keep={id:o.id,objectId:o.objectId,name:o.name,position:[...o.position],rotation:[...o.rotation],scale:[...o.scale],metadata:{...(o.metadata||{})}};for(const k of ['type','params','features','datums','geometryConstraints','components','motionAxes','sockets','color','materialProps'])if(src[k]!==undefined)o[k]=cloneData(src[k]);Object.assign(o,keep);scene?.rebuild?.(o);n++}return n}
